import{_ as e,c as r,o as n,ax as o}from"./chunks/framework.DHqKNX4U.js";const g=JSON.parse('{"title":"Microsoft 365 (Entra ID)","description":"","frontmatter":{},"headers":[],"relativePath":"enterprise/sso/examples/microsoft-365.md","filePath":"enterprise/sso/examples/microsoft-365.md"}'),a={name:"enterprise/sso/examples/microsoft-365.md"};function i(s,t,d,c,h,l){return n(),r("div",null,t[0]||(t[0]=[o('<h1 id="microsoft-365-entra-id" tabindex="-1">Microsoft 365 (Entra ID) <a class="header-anchor" href="#microsoft-365-entra-id" aria-label="Permalink to &quot;Microsoft 365 (Entra ID)&quot;">​</a></h1><p>Connect Open Archiver directly to Microsoft Entra ID, the identity service behind Microsoft 365, so that people sign in with their work or school account.</p><p>Entra ID supports both protocols fully, including group membership over either. OpenID Connect requires fewer steps and is the recommended choice unless your organisation standardises on SAML.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Detail</th></tr></thead><tbody><tr><td>License</td><td>Open Archiver Enterprise with the <strong>SSO</strong> feature enabled</td></tr><tr><td>Open Archiver role</td><td>Super Admin — single sign-on is configured under <strong>Admin → Single Sign-On</strong></td></tr><tr><td>Entra ID rights</td><td>Permission to create app registrations or enterprise applications, typically Application Administrator or Global Administrator</td></tr><tr><td>Application address</td><td><code>APP_URL</code> must be set to the address people use to reach Open Archiver. Every address exchanged with Entra ID derives from it.</td></tr></tbody></table><p>Open <strong>Admin → Single Sign-On</strong> and start a new connection before configuring Entra ID. The form displays the exact addresses to register; copy them from the page rather than retyping them.</p><table tabindex="0"><thead><tr><th>Address</th><th>Used by</th><th>Example</th></tr></thead><tbody><tr><td><strong>Redirect URI</strong></td><td>OpenID Connect</td><td><code>https://archive.example.com/signin/sso/callback</code></td></tr><tr><td><strong>Service provider metadata URL</strong></td><td>SAML 2.0</td><td><code>https://archive.example.com/api/v1/enterprise/sso/saml/metadata</code></td></tr><tr><td><strong>Assertion consumer service (ACS) URL</strong></td><td>SAML 2.0</td><td><code>https://archive.example.com/signin/sso/callback/saml</code></td></tr></tbody></table><p>Throughout this document, <code>archive.example.com</code> stands for your own Open Archiver address and <code>example.com</code> for your own Microsoft 365 domain.</p><hr><h2 id="openid-connect" tabindex="-1">OpenID Connect <a class="header-anchor" href="#openid-connect" aria-label="Permalink to &quot;OpenID Connect&quot;">​</a></h2><h3 id="part-1-—-register-the-application-in-entra-id" tabindex="-1">Part 1 — Register the application in Entra ID <a class="header-anchor" href="#part-1-—-register-the-application-in-entra-id" aria-label="Permalink to &quot;Part 1 — Register the application in Entra ID&quot;">​</a></h3><p>In the <a href="https://entra.microsoft.com/" target="_blank" rel="noreferrer">Microsoft Entra admin center</a>, go to <strong>Identity → Applications → App registrations → New registration</strong>.</p><ol><li><p>Complete the registration:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td>For example, <code>Open Archiver</code></td></tr><tr><td>Supported account types</td><td><strong>Accounts in this organizational directory only</strong></td></tr><tr><td>Redirect URI</td><td>Platform <strong>Web</strong>, value <code>https://archive.example.com/signin/sso/callback</code></td></tr></tbody></table></li><li><p>From the <strong>Overview</strong> page, note the <strong>Application (client) ID</strong> and the <strong>Directory (tenant) ID</strong>.</p></li><li><p>Go to <strong>Certificates &amp; secrets → Client secrets → New client secret</strong>. Set an expiry that matches your rotation policy, then copy the secret <strong>Value</strong> immediately — it is not shown again once you navigate away.</p><p>Note the expiry date. Sign-in stops working when the secret expires, and the fix is to create a new secret and update the connection.</p></li></ol><h3 id="part-2-—-add-the-groups-claim" tabindex="-1">Part 2 — Add the groups claim <a class="header-anchor" href="#part-2-—-add-the-groups-claim" aria-label="Permalink to &quot;Part 2 — Add the groups claim&quot;">​</a></h3><p>Skip this part if you do not intend to assign roles from directory groups.</p><p>In the app registration, go to <strong>Token configuration → Add groups claim</strong>.</p><ol><li><p>Select which groups to include. <strong>Security groups</strong> is the usual choice. <strong>Groups assigned to the application</strong> keeps tokens smaller and is preferable in large directories.</p></li><li><p>Expand <strong>ID</strong> under <em>Customize token properties by type</em> and choose to emit <strong>group names</strong> rather than group IDs, if readable names are wanted.</p></li></ol><div class="warning custom-block"><p class="custom-block-title">Entra ID sends group IDs unless you change this</p><p>By default the groups claim contains directory object IDs such as <code>f8c1e0a2-…</code>, not names such as <code>Finance</code>. Whichever format you choose, the <strong>Group mappings</strong> in Open Archiver must use exactly that format. Name-based emission applies to cloud groups; groups synchronised from on-premises Active Directory are identified by <code>sAMAccountName</code>.</p></div><h3 id="part-3-—-verify-the-email-claim" tabindex="-1">Part 3 — Verify the email claim <a class="header-anchor" href="#part-3-—-verify-the-email-claim" aria-label="Permalink to &quot;Part 3 — Verify the email claim&quot;">​</a></h3><p>Open Archiver requires an email address in the token and refuses a sign-in without one.</p><p>Entra ID supplies an address for accounts whose <strong>mail</strong> attribute is populated. If some accounts in your directory leave it unset, add the claim explicitly: <strong>Token configuration → Add optional claim → ID → <code>email</code></strong>.</p><h3 id="part-4-—-create-the-connection-in-open-archiver" tabindex="-1">Part 4 — Create the connection in Open Archiver <a class="header-anchor" href="#part-4-—-create-the-connection-in-open-archiver" aria-label="Permalink to &quot;Part 4 — Create the connection in Open Archiver&quot;">​</a></h3><p><strong>Identity provider</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Protocol</td><td><strong>OpenID Connect</strong></td></tr><tr><td>Display name</td><td><code>Microsoft 365</code> — appears on the sign-in page as &quot;Continue with Microsoft 365&quot;</td></tr><tr><td>Issuer URL</td><td><code>https://login.microsoftonline.com/&lt;tenant-id&gt;/v2.0</code></td></tr><tr><td>Client ID</td><td>The Application (client) ID from Part 1</td></tr><tr><td>Client secret</td><td>The secret <strong>Value</strong> from Part 1</td></tr></tbody></table><p>The issuer must include the <code>/v2.0</code> suffix and your own tenant ID. Omitting the suffix produces a configuration that cannot be read.</p><p><strong>Accounts</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Allowed email domains</td><td>Your Microsoft 365 domain, for example <code>example.com</code>. At least one entry is required; press Enter after each domain.</td></tr><tr><td>Create accounts on first sign-in</td><td><strong>On</strong>, so people receive an account the first time they sign in</td></tr><tr><td>Link to existing accounts</td><td><strong>On</strong>, so a person who already has an Open Archiver account keeps it</td></tr></tbody></table><p>Enter the domain that appears in your users&#39; email addresses. In tenants that use a vanity domain, this is that domain — not the <code>onmicrosoft.com</code> tenant name.</p><p><strong>Roles</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Groups claim</td><td><code>groups</code></td></tr><tr><td>Group mappings</td><td>The group name or object ID on the left — matching the format chosen in Part 2 — and the role on the right</td></tr><tr><td>Default role</td><td>Recommended, as the fallback for anyone matching no mapping</td></tr><tr><td>Update roles on every sign-in</td><td><strong>On</strong>, so directory group changes take effect at the next sign-in</td></tr></tbody></table><h3 id="part-5-—-test-then-enable" tabindex="-1">Part 5 — Test, then enable <a class="header-anchor" href="#part-5-—-test-then-enable" aria-label="Permalink to &quot;Part 5 — Test, then enable&quot;">​</a></h3><ol><li>Select <strong>Test connection</strong>. A successful test confirms Open Archiver can reach Entra ID and read its configuration.</li><li>Turn on <strong>Enable this connection</strong>.</li><li>Save.</li></ol><hr><h2 id="saml-2-0" tabindex="-1">SAML 2.0 <a class="header-anchor" href="#saml-2-0" aria-label="Permalink to &quot;SAML 2.0&quot;">​</a></h2><h3 id="part-1-—-create-the-enterprise-application" tabindex="-1">Part 1 — Create the enterprise application <a class="header-anchor" href="#part-1-—-create-the-enterprise-application" aria-label="Permalink to &quot;Part 1 — Create the enterprise application&quot;">​</a></h3><p>In the <a href="https://entra.microsoft.com/" target="_blank" rel="noreferrer">Microsoft Entra admin center</a>, go to <strong>Identity → Applications → Enterprise applications → New application → Create your own application</strong>. Select <strong>Integrate any other application you don&#39;t find in the gallery</strong>, name it, and create it.</p><p>Open <strong>Single sign-on → SAML</strong> and complete the sections below.</p><ol><li><p><strong>Basic SAML Configuration</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Identifier (Entity ID)</td><td><code>https://archive.example.com/api/v1/enterprise/sso/saml/metadata</code></td></tr><tr><td>Reply URL (Assertion Consumer Service URL)</td><td><code>https://archive.example.com/signin/sso/callback/saml</code></td></tr></tbody></table><p>Leave <strong>Sign on URL</strong> empty. Open Archiver always begins sign-in from its own sign-in page.</p></li><li><p><strong>Attributes &amp; Claims</strong> — confirm the unique user identifier (Name ID) is <code>user.mail</code> or <code>user.userprincipalname</code>, in email format.</p><p>Then select <strong>Add a group claim</strong>, choose which groups to emit, and under the advanced options choose whether groups are identified by name or by object ID. Name the claim <code>groups</code>.</p></li><li><p><strong>SAML Certificates</strong> — copy the <strong>App Federation Metadata Url</strong>.</p></li><li><p><strong>Users and groups</strong> — assign the people or groups who should have access. Entra ID refuses sign-in for anyone not assigned.</p></li></ol><h3 id="part-2-—-create-the-connection-in-open-archiver" tabindex="-1">Part 2 — Create the connection in Open Archiver <a class="header-anchor" href="#part-2-—-create-the-connection-in-open-archiver" aria-label="Permalink to &quot;Part 2 — Create the connection in Open Archiver&quot;">​</a></h3><p><strong>Identity provider</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Protocol</td><td><strong>SAML 2.0</strong></td></tr><tr><td>Display name</td><td><code>Microsoft 365</code></td></tr><tr><td>IdP metadata URL</td><td>The <strong>App Federation Metadata Url</strong> from Part 1</td></tr><tr><td>IdP metadata XML</td><td>Leave empty. Entra ID&#39;s metadata address is reachable and keeps certificate changes current automatically.</td></tr></tbody></table><p><strong>Accounts</strong> and <strong>Roles</strong> — as for OpenID Connect above, with <strong>Groups claim</strong> set to <code>groups</code>.</p><h3 id="part-3-—-test-then-enable" tabindex="-1">Part 3 — Test, then enable <a class="header-anchor" href="#part-3-—-test-then-enable" aria-label="Permalink to &quot;Part 3 — Test, then enable&quot;">​</a></h3><p>As for OpenID Connect. A successful SAML test reports the sign-in address and the number of signing certificates found in the metadata.</p><hr><h2 id="verify-the-first-sign-in" tabindex="-1">Verify the first sign-in <a class="header-anchor" href="#verify-the-first-sign-in" aria-label="Permalink to &quot;Verify the first sign-in&quot;">​</a></h2><p>Sign in from a private browser window, so an existing Microsoft session does not mask the flow.</p><ol><li>Open the Open Archiver sign-in page and select <strong>Continue with Microsoft 365</strong>.</li><li>Complete Microsoft&#39;s sign-in.</li><li>Confirm you arrive at the dashboard.</li></ol><p>Then check the following as an administrator:</p><table tabindex="0"><thead><tr><th>Where</th><th>What to confirm</th></tr></thead><tbody><tr><td><strong>Settings → Users</strong></td><td>The account exists with the role its groups should grant</td></tr><tr><td><strong>Compliance → Audit Log</strong></td><td>An account-creation entry for a first sign-in, and a sign-in entry for every one</td></tr><tr><td><strong>Settings → Account</strong> (as that user)</td><td>Password management is hidden for accounts created through single sign-on</td></tr></tbody></table><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>Failed sign-ins show the same brief message to the person signing in. The explanation is recorded in <strong>Compliance → Audit Log</strong>, where each failed sign-in entry names the connection, the address the provider supplied, and the domains the connection permits.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Resolution</th></tr></thead><tbody><tr><td>Sign-in fails; audit log reports a domain that is not allowed</td><td>The address Entra ID supplied is not in <strong>Allowed email domains</strong></td><td>Add the domain shown in the audit entry. Check whether your tenant sends a vanity domain or an <code>onmicrosoft.com</code> address.</td></tr><tr><td>Sign-in fails; audit log reports a missing email address</td><td>The account has no <strong>mail</strong> attribute and no <code>email</code> optional claim is configured</td><td>Populate the attribute, or add the <code>email</code> optional claim as described in Part 3</td></tr><tr><td>Sign-in fails; audit log reports no role could be determined</td><td>A new account matched no group mapping and no default role is set</td><td>Set a <strong>Default role</strong></td></tr><tr><td>Sign-in succeeds but the role is the default, not the mapped one</td><td>Mappings use names while the token carries object IDs, or the reverse</td><td>Compare the format chosen in Part 2 against the values in <strong>Group mappings</strong></td></tr><tr><td>Sign-in worked previously and now fails for everyone</td><td>The client secret has expired</td><td>Create a new secret in <strong>Certificates &amp; secrets</strong> and update the connection</td></tr><tr><td>Microsoft reports the user is not assigned</td><td>The person is not in the application&#39;s <strong>Users and groups</strong> list (SAML)</td><td>Assign them, or the group they belong to</td></tr><tr><td>No sign-in button appears</td><td>The connection is not enabled, or the license does not include SSO</td><td>Enable the connection; confirm the license under <strong>Admin → License</strong></td></tr></tbody></table><hr><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><strong>Group limits.</strong> Entra ID includes at most 200 groups in an OpenID Connect token and 150 in a SAML assertion, nested groups included. Where a person may exceed the limit, restrict the claim to <strong>Groups assigned to the application</strong>.</li><li><strong>Certificate rollover.</strong> Entra ID signing certificates expire, typically after three years. Because Open Archiver reads the metadata address rather than a stored copy, a rotated certificate is picked up without intervention. This is why the metadata URL is preferred over pasted XML.</li><li><strong>Client secret expiry.</strong> Unlike the certificate, an expired client secret must be replaced by hand. Record the expiry date when you create it.</li><li><strong>Signing out.</strong> Signing out of Open Archiver does not end the Microsoft session. Use a private window when testing repeatedly.</li></ul><p>For the roles model, running several providers at once, and requiring single sign-on, see the <a href="./../guide.html">SSO guide</a>.</p>',58)]))}const u=e(a,[["render",i]]);export{g as __pageData,u as default};
